\def\axwidth{0.4}



\newcommand{\myCone}[6]{

%\draw[draw=none, fill=white]
%	plot[variable=\x, domain={0}:{pi}, samples={\nsamples/2}]
%(axis cs: {#3*cos(deg(\x))+#1}, {#4*sin(deg(\x))+#2}, {0})
%	-- plot[variable=\x, domain={pi}:{2*pi}, samples={\nsamples/2}]
%(axis cs: {#3*cos(deg(\x))+#1}, {#4*sin(deg(\x))+#2}, {0});

\plot3[
	surf,
	shader = faceted interp,
	opacity=1,
	samples = {\nsamples/2},
	samples y=\nsamples,
	draw=#6!90!black, ultra thin,
	colormap={custom}{color(0)=(#6!\LowSat) color(1)=(#6!\HighSat)},
	z buffer=sort, domain=-1:0, y domain=0:{2*pi}
	]
	({#3*x*cos(deg(y))+#1},{#4*x*sin(deg(y))+#2},{#5*(x+1)});

% Label
%\node[circle, draw=none, fill=orangepeel, inner sep=1pt, label={[above=-3pt, xshift=5pt]:{\scriptsize $(#1,#2,#5)$}}] at (axis cs: #1,#2,#5) {};
%\node[circle, draw=none, fill=orangepeel, inner sep=1pt, label={[above=-3pt, xshift=5pt]:{\scriptsize \pgfmathparse{#5/#6} $(#1,#2,\pgfmathprintnumber{\pgfmathresult})$}}] at (axis cs: #1,#2,{#5/#6}) {};
}






