\newcommand{\mySaddle}[5]{
% Negative x Side (DONE)
\begin{scope}
\clip[]
	plot[variable=\x, domain=-1:1, samples=\nsamples]
(axis cs: {#1-1-sqrt(1-(\x)^2)}, {\x+#2}, {0})
	-- (axis cs: {#1}, {1+#2}, {0})
	-- (axis cs: {#1}, {#2-1}, {0})
	-- cycle;

\plot3[
	surf,
	shader = faceted interp,
	opacity=1,
	samples = {\nsamples/4},
	samples y={\nsamples/2},
	draw=#4!90!black, ultra thin,
	colormap={custom}{color(0)=(#4!\LowSat) color(1)=(#4!\HighSat)},
	z buffer=sort, domain=-1:0, y domain=-1:1
	]
	({x+#1-1},{y+#2},{#3*(x^2+y^2-1)});
\end{scope}



% Negative y Side
\begin{scope}
\clip[]
	plot[variable=\x, domain=0.1:1, samples=\nsamples]
(axis cs: {\x+#1}, {#2-1-sqrt(1-(\x)^2)}, {0})
	--  (axis cs: {0+#1}, {0+#2}, {0})
	--  (axis cs: {#1}, {#2-1}, {1.1*#3})
	--  (axis cs: {0.1+#1}, {#2-1-sqrt(1-(0.1)^2)}, {1.1*#3})
	--cycle;

\plot3[
	surf,
	shader = faceted interp,
	opacity=1,
	samples = {\nsamples/2},
	samples y={\nsamples/4},
	draw=#4!90!black, ultra thin,
	colormap={custom}{color(0)=(#4!\LowSat) color(1)=(#4!\HighSat)},
	z buffer=sort, domain=-1:1, y domain=-1:0
]
	({x+#1},{y+#2-1},{#3*(1-x^2-y^2)});
\end{scope}


% Main Saddle (Top)
\begin{scope}
\clip[]
	plot[variable=\x, domain=-1:1, samples=\nsamples]
(axis cs: {#1+1+sqrt(1-(\x)^2)}, {\x+#2}, {0})
	-- (axis cs: {-1+#1}, {1+#2}, {0})
	-- (axis cs: {-1+#1}, {1+#2}, {1.1*#3})
	-- (axis cs: {-1+#1}, {#2-1}, {1.1*#3})
	-- (axis cs: {1+#1}, {#2-1}, {1.1*#3})
	-- cycle;

\plot3[
	surf,
	shader = faceted interp,
	opacity=1,
	samples = {\nsamples/2},
	samples y={\nsamples/2},
	draw=#4!90!black, ultra thin,
	colormap={custom}{color(0)=(#4!\LowSat) color(1)=(#4!\HighSat)},
	z buffer=sort, domain=-1:1, y domain=-1:1
	]
	({x+#1},{y+#2},{#3*y^2-#3*x^2});
\end{scope}


% Positive y Side
\begin{scope}
\clip[]
	plot[variable=\x, domain=-0.5:1, samples=\nsamples]
(axis cs: {\x+#1}, {#2+1+sqrt(1-(\x)^2)}, {0})
	--  (axis cs: {0+#1}, {0+#2}, {0})
	--  (axis cs: {#1}, {#2+1}, {1.1*#3})
	--  (axis cs: {#1-0.5}, {#2+1+sqrt(1-(-0.5)^2)}, {1.1*#3})
	--cycle;

\plot3[
	surf,
	shader = faceted interp,
	opacity=1,
	samples = {\nsamples/2},
	samples y={\nsamples/4},
	draw=#4!90!black, ultra thin,
	colormap={custom}{color(0)=(#4!\LowSat) color(1)=(#4!\HighSat)},
	z buffer=sort, domain=-1:1, y domain=0:1
	]
	({x+#1},{y+#2+1},{#3*(1-x^2-y^2)});
\end{scope}
}


\newcommand{\mySaddleBelow}[5]{
% Positive x Side
\begin{scope}
\clip[]
	plot[variable=\x, domain=-1:1, samples=\nsamples]
(axis cs: {#1+1+sqrt(1-(\x)^2)}, {\x+#2}, {0})
	-- plot[variable=\x, domain=1:-1, samples=\nsamples]
(axis cs: {1+#1}, {\x+#2}, {#3*((\x)^2-1)});

\plot3[
	surf,
	shader = faceted interp,
	opacity=1,
	samples = {\nsamples/4},
	samples y={\nsamples/2},
	draw=#4!90!black, ultra thin,
	colormap={custom}{color(0)=(#4!\LowSat) color(1)=(#4!\HighSat)},
	z buffer=sort, domain=0:1, y domain=-1:1
	]
	({x+1+#1},{y+#2},{#3*(x^2+y^2-1)});
\end{scope}
}





\newcommand{\myCircularRegion}[5]{
\draw[draw=#5, dashed, fill=#5!50, fill opacity=0.25]
	plot[variable=\x, domain={0}:{2*pi}, samples={\nsamples/2}]
(axis cs: {#3*cos(deg(\x))+#1}, {#3*sin(deg(\x))+#2}, {#4});
}




\newcommand{\myCircularSaddleRegion}[5]{
\draw[draw=none, fill=#5!50, fill opacity=0.5]
	plot[variable=\x, domain={-1.1}:{1.1}, samples={\nsamples/2}]
(axis cs: {#3*cos(deg(\x))+#1}, {#3*sin(deg(\x))+#2}, {#4})
	-- (axis cs: {#1}, {#2}, {0})
	-- plot[variable=\x, domain={3}:{3.9}, samples={\nsamples/2}]
(axis cs: {#3*cos(deg(\x))+#1}, {#3*sin(deg(\x))+#2}, {#4})
	-- (axis cs: {#1}, {#2}, {0})
	-- cycle;

\draw[draw=#5, dashed]
	plot[variable=\x, domain={-1.1}:{1.1}, samples={\nsamples/2}]
(axis cs: {#3*cos(deg(\x))+#1}, {#3*sin(deg(\x))+#2}, {#4});
\draw[draw=#5, dashed]
	plot[variable=\x, domain={3}:{3.9}, samples={\nsamples/2}]
(axis cs: {#3*cos(deg(\x))+#1}, {#3*sin(deg(\x))+#2}, {#4});
}


